## In-Memory Data Store

### Basic Operations

```xiom
use xiom.redis;

fn main() -> Int {
  let client = redis::Client::new("redis://localhost:6379")?;

  // Set and get
  client.set("key", "value")?;
  let value = client.get("key")?;

  // With expiration
  client.setex("session:abc123", "user_data", 3600)?;  // 1 hour

  // Increment
  let views = client.incr("page:home:views")?;

  // Check existence
  if client.exists("key")? {
    io.println("Key exists!");
  }
  return 0;
}
```

### Lists and Queues

```xiom
// Task queue
client.lpush("tasks", "send_email:123")?;
client.lpush("tasks", "generate_report:456")?;

// Process tasks (FIFO)
while let Some(task) = client.rpop("tasks")? {
  process_task(task);
}

// Blocking pop (wait for items)
let task = client.brpop("tasks", timeout: 5)?;
```

### Hashes

```xiom
// Store user profile
client.hset("user:1", "name", "Alice")?;
client.hset("user:1", "email", "alice@example.com")?;
client.hset("user:1", "age", "30")?;

// Get all fields
let profile = client.hgetall("user:1")?;
io.println(profile["name"]);  // "Alice"

// Get specific field
let email = client.hget("user:1", "email")?;
```

### Sets and Sorted Sets

```xiom
// Unique tags
client.sadd("article:1:tags", "xiom")?;
client.sadd("article:1:tags", "programming")?;
let tags = client.smembers("article:1:tags")?;

// Leaderboard (sorted set)
client.zadd("leaderboard", "Alice", 1500)?;
client.zadd("leaderboard", "Bob", 1200)?;
let top3 = client.zrevrange("leaderboard", 0, 2)?;

// Get rank
let alice_rank = client.zrevrank("leaderboard", "Alice")?;
```

### Pub/Sub

```xiom
// Publisher
client.publish("notifications", "New user registered: Alice")?;

// Subscriber
let mut sub = client.subscribe("notifications")?;
for message in sub.messages() {
  io.println("Received: " + message);
  handle_notification(message);
}
```

### Connection Pool

```xiom
let pool = redis::Pool::new("redis://localhost:6379", size: 10)?;

// In request handler:
let conn = pool.get()?;
conn.get("key")?;
// conn is automatically returned to pool when dropped
```

